"""hexspanner_exact: parametric CadQuery model generated by stl2cad (exact mode, 2.5D).

The part is built along +z from 1 extrusion(s) and 1 cut(s), applied in order;
each is an outline in the xy plane between two levels. Units: mm.
Run:  python hexspanner_exact.py [out.step]
"""

import math
import sys

from cadquery import Edge, Vector
from cadquery import func as cf

# ---- parameters ----------------------------------------------------------
z0 = 0.0    # level along z
z1 = 7.62    # level along z

DIR = (0, 0, 1)


def P(a, b):
    """Point (x, y) in the sketch plane (z = 0)."""
    return (a, b, 0)


def prism(outline, lo, hi):
    """Outline extruded from level lo to level hi."""
    body = cf.extrude(cf.face(outline), [(hi - lo) * c for c in DIR])
    return body.translate(Vector(*[lo * c for c in DIR]))


def hole(a, b, d, lo, hi):
    return prism(Edge.makeCircle(d / 2, P(a, b), DIR), lo, hi)


# ---- 1. extrusion: z 0.0 to 7.62 ------------------------------
outline_1 = cf.wire(
    cf.segment(P(0.0, 0.0), P(-3.6662, 6.35)),
    cf.segment(P(-3.6662, 6.35), P(-10.16, 6.35)),
    cf.segment(P(-10.16, 6.35), P(-10.16, 7.9311)),
    Edge.makeThreePointArc(P(-10.16, 7.9311), P(-1.9308, 9.9847), P(4.9888, 5.08)),
    cf.segment(P(4.9888, 5.08), P(87.5434, 5.08)),
    Edge.makeThreePointArc(P(87.5434, 5.08), P(106.5022, 0.0), P(87.5434, -5.08)),
    cf.segment(P(87.5434, -5.08), P(4.9888, -5.08)),
    Edge.makeThreePointArc(P(4.9888, -5.08), P(-1.9308, -9.9847), P(-10.16, -7.9311)),
    cf.segment(P(-10.16, -7.9311), P(-10.16, -6.35)),
    cf.segment(P(-10.16, -6.35), P(-3.6662, -6.35)),
    cf.segment(P(-3.6662, -6.35), P(0.0, 0.0)),
)
part = prism(outline_1, z0, z1)

# ---- 2. cut: z 0.0 to 7.62 ------------------------------
outline_2 = cf.wire(
    cf.segment(P(103.67, 0.0), P(100.0038, 6.35)),
    cf.segment(P(100.0038, 6.35), P(92.6715, 6.35)),
    cf.segment(P(92.6715, 6.35), P(89.0053, 0.0)),
    cf.segment(P(89.0053, 0.0), P(92.6715, -6.35)),
    cf.segment(P(92.6715, -6.35), P(100.0038, -6.35)),
    cf.segment(P(100.0038, -6.35), P(103.67, 0.0)),
)
part = part - prism(outline_2, z0, z1)

part = part.clean()

if __name__ == "__main__":
    part.exportStep(sys.argv[1] if len(sys.argv) > 1 else "hexspanner_exact.step")
